"""
k8s-docs-es-review — main orchestrator.

Usage:
    python3 review_pr.py --pr 12345 [--repo URL] [--out PATH] [--keep-tmp]
"""

import argparse
import json
import os
import re
import shutil
import ssl
import subprocess
import sys
import tempfile
import unicodedata
import urllib.request
from datetime import datetime, timezone
from pathlib import Path

REPO_DEFAULT = "https://github.com/kubernetes/website"
GITHUB_API = "https://api.github.com"


def github_urlopen(req: urllib.request.Request, timeout: int = 30):
    """Open a GitHub API request with the configured CA bundle when available."""
    cafile = os.environ.get("SSL_CERT_FILE")
    if cafile and os.path.exists(cafile):
        context = ssl.create_default_context(cafile=cafile)
        return urllib.request.urlopen(req, timeout=timeout, context=context)
    return urllib.request.urlopen(req, timeout=timeout)


def run(
    cmd: list[str], cwd: str | None = None, check: bool = True
) -> subprocess.CompletedProcess:
    """Run a subprocess and return its completed process result."""
    return subprocess.run(cmd, cwd=cwd, capture_output=True, text=True, check=check)


def clone_and_fetch(repo_url: str, pr_number: int, tmp_dir: str) -> str:
    """Sparse-clone the repo, fetch the base branch, and then the PR branch."""
    repo_path = os.path.join(tmp_dir, "website")
    print(f"[1/4] Cloning {repo_url} (sparse) …", flush=True)
    run(
        [
            "git",
            "clone",
            "--depth",
            "1",
            "--filter=blob:none",
            "--sparse",
            repo_url,
            repo_path,
        ]
    )
    run(["git", "sparse-checkout", "set", "content/en", "content/es"], cwd=repo_path)
    _, base_ref = get_pr_base_details_from_api(repo_url, pr_number)
    target_branch = "main"
    if base_ref:
        target_branch = base_ref
    print(f"[1/4] Fetching target branch '{target_branch}' and PR #{pr_number} …", flush=True)
    run(["git", "fetch", "origin", f"{target_branch}", "--depth=1"], cwd=repo_path, check=False)
    run(["git", "fetch", "origin", f"pull/{pr_number}/head:pr-branch"], cwd=repo_path)
    run(["git", "checkout", "pr-branch"], cwd=repo_path)
    return repo_path


def get_changed_es_files_from_api(repo_url: str, pr_number: int) -> list[str]:
    """Use GitHub API to list changed content/es/** .md files in the PR."""
    # Derive owner/repo from URL  (https://github.com/owner/repo)
    parts = repo_url.rstrip("/").split("/")
    owner, repo = parts[-2], parts[-1]
    api_url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{pr_number}/files?per_page=100"
    req = urllib.request.Request(
        api_url, headers={"Accept": "application/vnd.github+json"}
    )
    try:
        with github_urlopen(req, timeout=30) as resp:
            files_data = json.loads(resp.read())
    except (OSError, ValueError, TypeError) as exc:
        print(
            f"  WARNING: GitHub API call failed ({exc}). Falling back to git diff.",
            flush=True,
        )
        return []
    return [
        f["filename"]
        for f in files_data
        if f["filename"].startswith("content/es/") and f["filename"].endswith(".md")
    ]


def get_pr_base_details_from_api(
    repo_url: str, pr_number: int
) -> tuple[str | None, str | None]:
    """Return (base_repo_html_url, base_ref) for the PR, if available."""
    parts = repo_url.rstrip("/").split("/")
    owner, repo = parts[-2], parts[-1]
    api_url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{pr_number}"
    req = urllib.request.Request(
        api_url, headers={"Accept": "application/vnd.github+json"}
    )
    try:
        with github_urlopen(req, timeout=30) as resp:
            pr_data = json.loads(resp.read())
    except (OSError, ValueError, TypeError) as exc:
        print(
            f"  WARNING: Could not resolve PR base branch from API ({exc}).",
            flush=True,
        )
        return None, None

    base = pr_data.get("base") or {}
    base_repo = (base.get("repo") or {}).get("html_url")
    base_ref = base.get("ref")
    return base_repo, base_ref


def get_pr_head_details_from_api(
    repo_url: str, pr_number: int
) -> tuple[str | None, str | None]:
    """Return (head_repo_html_url, head_sha) for the PR, if available."""
    parts = repo_url.rstrip("/").split("/")
    owner, repo = parts[-2], parts[-1]
    api_url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{pr_number}"
    req = urllib.request.Request(
        api_url, headers={"Accept": "application/vnd.github+json"}
    )
    try:
        with github_urlopen(req, timeout=30) as resp:
            pr_data = json.loads(resp.read())
    except (OSError, ValueError, TypeError) as exc:
        print(
            f"  WARNING: Could not resolve PR head repo/ref from API ({exc}).",
            flush=True,
        )
        return None, None

    head = pr_data.get("head") or {}
    head_repo = (head.get("repo") or {}).get("html_url")
    head_sha = head.get("sha")
    return head_repo, head_sha


def _github_paginated_json(url: str) -> list[dict]:
    """Fetch all public pages from a GitHub REST collection."""
    items: list[dict] = []
    page = 1
    while True:
        req = urllib.request.Request(
            f"{url}?per_page=100&page={page}",
            headers={"Accept": "application/vnd.github+json"},
        )
        with github_urlopen(req, timeout=30) as resp:
            batch = json.loads(resp.read())
        if not isinstance(batch, list):
            raise TypeError(f"Expected a list from {url}")
        items.extend(item for item in batch if isinstance(item, dict))
        if len(batch) < 100:
            return items
        page += 1


def get_existing_pr_comments(
    repo_url: str, pr_number: int
) -> tuple[list[dict], list[str]]:
    """Return issue, review, and inline comments for duplicate-finding suppression."""
    parts = repo_url.rstrip("/").split("/")
    owner, repo = parts[-2], parts[-1]
    base = f"{GITHUB_API}/repos/{owner}/{repo}"
    comments: list[dict] = []
    errors: list[str] = []
    endpoints = [
        (f"{base}/issues/{pr_number}/comments", "issue-comment"),
        (f"{base}/pulls/{pr_number}/reviews", "review"),
        (f"{base}/pulls/{pr_number}/comments", "inline-comment"),
    ]
    for url, source in endpoints:
        try:
            for item in _github_paginated_json(url):
                body = (item.get("body") or "").strip()
                if not body:
                    continue
                comments.append(
                    {
                        "source": source,
                        "id": item.get("id"),
                        "body": body,
                        "path": item.get("path", ""),
                        "line": item.get("line") or item.get("original_line"),
                        "html_url": item.get("html_url", ""),
                    }
                )
        except (OSError, ValueError, TypeError) as exc:
            errors.append(f"{source}: {exc}")
    return comments, errors


def get_changed_line_map(repo_path: str, files: list[str], base_ref: str = "main") -> dict[str, set[int]]:
    """Return added/modified line numbers from the PR diff, keyed by repo path."""
    result = run(
        ["git", "diff", "--unified=0", f"origin/{base_ref}", "pr-branch", "--", *files],
        cwd=repo_path,
        check=False,
    )
    line_map = {file_path: set() for file_path in files}
    current_file = ""
    for line in result.stdout.splitlines():
        if line.startswith("+++ b/"):
            current_file = line[6:]
            continue
        match = re.match(r"^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@", line)
        if not match or current_file not in line_map:
            continue
        start = int(match.group(1))
        count = int(match.group(2) or 1)
        line_map[current_file].update(range(start, start + count))
    return line_map


def _comment_tokens(text: str) -> set[str]:
    """Extract normalized distinctive tokens from a review comment."""
    normalized = unicodedata.normalize("NFKD", text.lower())
    normalized = "".join(c for c in normalized if not unicodedata.combining(c))
    tokens = set(re.findall(r"[a-z0-9][a-z0-9_-]{2,}", normalized))
    return tokens - {"para", "linea", "usar", "cambiar", "review", "please"}


def _comment_matches_finding(comment: dict, finding: dict) -> tuple[bool, str]:
    """Return whether a prior comment likely addresses a finding."""
    body = comment.get("body", "")
    path = comment.get("path", "")
    finding_file = finding.get("file", "")
    finding_line = finding.get("line", 0)
    comment_line = comment.get("line")
    same_path = path == finding_file or path == finding_file.removeprefix("content/es/")
    if (
        same_path
        and isinstance(comment_line, int)
        and isinstance(finding_line, int)
        and abs(comment_line - finding_line) <= 10
    ):
        return True, "inline comment on the same file and nearby line"

    code = finding.get("code", "")
    if code and code.lower() in body.lower():
        return True, "comment names the same finding code"

    body_tokens = _comment_tokens(body)
    finding_tokens = _comment_tokens(
        " ".join(
            [
                finding.get("line_text", ""),
                finding.get("message", ""),
                finding.get("suggestion", ""),
            ]
        )
    )
    overlap = body_tokens & finding_tokens
    file_mentioned = finding_file in body or finding_file.rsplit("/", 1)[-1] in body
    line_mentioned = bool(
        isinstance(finding_line, int)
        and re.search(rf"\b(?:line|linea|l)\s*#?\s*{finding_line}\b", body.lower())
    )
    if (file_mentioned or same_path) and len(overlap) >= 2:
        return True, "comment names the file and shares distinctive finding terms"
    if line_mentioned and len(overlap) >= 2:
        return True, "comment names the line and shares distinctive finding terms"
    return False, ""


def suppress_existing_comment_findings(
    findings: list[dict], comments: list[dict]
) -> tuple[list[dict], list[dict]]:
    """Remove findings already addressed in a PR comment and return an audit trail."""
    kept: list[dict] = []
    suppressed: list[dict] = []
    for finding in findings:
        match = next(
            (
                (comment, reason)
                for comment in comments
                for matched, reason in [_comment_matches_finding(comment, finding)]
                if matched
            ),
            None,
        )
        if match is None:
            kept.append(finding)
            continue
        comment, reason = match
        suppressed.append({"finding": finding, "comment": comment, "reason": reason})
    return kept, suppressed


def filter_findings_file(
    path: str, comments: list[dict], changed_line_map: dict[str, set[int]]
) -> tuple[list[dict], list[dict]]:
    """Suppress duplicate and out-of-diff findings in a JSON artifact."""
    data = json.loads(Path(path).read_text())
    data["findings"], suppressed = suppress_existing_comment_findings(
        data.get("findings", []), comments
    )
    scope_suppressed = []
    in_scope = []
    for finding in data["findings"]:
        finding_changed_lines = changed_line_map.get(finding.get("file", ""), set())
        finding_line = finding.get("line")
        finding_end = finding.get("line_end", finding_line)
        if (
            isinstance(finding_line, int)
            and isinstance(finding_end, int)
            and any(
                line in finding_changed_lines
                for line in range(finding_line, finding_end + 1)
            )
        ):
            in_scope.append(finding)
        else:
            scope_suppressed.append(
                {"finding": finding, "reason": "line is outside the contributor diff"}
            )
    data["findings"] = in_scope
    data["suppressed_findings"] = suppressed
    data["out_of_scope_findings"] = scope_suppressed
    Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2))
    return suppressed, scope_suppressed


def run_script(script: str, args: list[str]) -> subprocess.CompletedProcess:
    """Run a companion script; on failure, write an empty findings JSON to --out."""
    script_path = Path(__file__).parent / script
    cmd = [sys.executable, str(script_path)] + args
    print(f"  → {script}", flush=True)
    result = subprocess.run(cmd, capture_output=True, text=True, check=False)
    if result.returncode != 0:
        print(
            f"    WARNING: {script} exited {result.returncode}\n{result.stderr[:800]}",
            flush=True,
        )
        # Write an empty-but-valid JSON so the report generator can continue
        try:
            out_idx = args.index("--out")
            out_path = Path(args[out_idx + 1])
            if not out_path.exists():
                out_path.write_text(
                    json.dumps(
                        {"findings": [], "errors": [[script, result.stderr[:200]]]}
                    )
                )
        except (ValueError, IndexError):
            pass
    return result


def validate_results(paragraphs_out: str, links_out: str, style_out: str) -> list[str]:
    """Validate that checker outputs exist and contain JSON objects."""
    errors = []
    for path, label in [
        (paragraphs_out, "paragraphs"),
        (links_out, "links"),
        (style_out, "style"),
    ]:
        if not os.path.exists(path):
            errors.append(f"Missing output: {label} ({path})")
            continue
        with open(path) as f:
            data = json.load(f)
        if not isinstance(data, dict):
            errors.append(f"Invalid JSON shape in {label}")
    return errors


def main() -> None:
    """Run all review checks for a pull request and write report artifacts."""
    parser = argparse.ArgumentParser(description="k8s Spanish PR reviewer")
    parser.add_argument("--pr", type=int, required=True, help="GitHub PR number")
    parser.add_argument("--repo", default=REPO_DEFAULT, help="Repository URL")
    parser.add_argument("--out", default=None, help="Output report path")
    parser.add_argument(
        "--comment-out",
        default=None,
        help="Optional output path for a compact PR comment Markdown artifact",
    )
    parser.add_argument(
        "--keep-tmp", action="store_true", help="Keep temp directory after run"
    )
    parser.add_argument(
        "--save-findings",
        default=None,
        metavar="PATH",
        help="Save combined findings JSON for use as --base-findings in a follow-up review",
    )
    parser.add_argument(
        "--base-findings",
        default=None,
        metavar="PATH",
        help="Findings JSON from a previous review; enables follow-up mode",
    )
    args = parser.parse_args()

    out_path = args.out or (
        f"./reports/k8s-review-PR{args.pr}-{datetime.now(timezone.utc).date()}.md"
    )
    comment_out_path = args.comment_out
    if comment_out_path is None:
        out_path_obj = Path(out_path)
        comment_out_path = str(
            out_path_obj.with_name(f"{out_path_obj.stem}-comment{out_path_obj.suffix}")
        )
    Path(out_path).parent.mkdir(parents=True, exist_ok=True)
    Path(comment_out_path).parent.mkdir(parents=True, exist_ok=True)

    tmp_dir = tempfile.mkdtemp(prefix="k8s_review_")
    try:
        repo_path = clone_and_fetch(args.repo, args.pr, tmp_dir)
        _, base_ref = get_pr_base_details_from_api(args.repo, args.pr)
        if not base_ref:
            base_ref = "main"
        head_repo, head_ref = get_pr_head_details_from_api(args.repo, args.pr)
        if not head_ref:
            head_ref = run(["git", "rev-parse", "HEAD"], cwd=repo_path).stdout.strip()
        if not head_repo:
            head_repo = args.repo

        print("[2/4] Identifying changed Spanish files …", flush=True)
        changed = get_changed_es_files_from_api(args.repo, args.pr)
        if not changed:
            print(
                "No content/es/** Markdown files changed in this PR. Nothing to review."
            )
            sys.exit(0)

        # Ensure sparse checkout includes all changed ES paths (and their EN mirrors)
        es_dirs = {"/".join(f.split("/")[:-1]) for f in changed}
        en_dirs = {d.replace("content/es/", "content/en/", 1) for d in es_dirs}
        run(
            ["git", "sparse-checkout", "add"] + sorted(es_dirs | en_dirs), cwd=repo_path
        )

        print(f"  Files to review: {len(changed)}")
        for f in changed:
            print(f"    {f}")

        files_to_check = [f for f in changed if (Path(repo_path) / f).is_file()]
        skipped_deleted = len(changed) - len(files_to_check)
        if skipped_deleted:
            print(f"  Skipping {skipped_deleted} deleted file(s) in content checks")

        files_arg = ",".join(files_to_check)
        reviewed_files_arg = ",".join(changed)
        changed_line_map = get_changed_line_map(repo_path, changed, base_ref=base_ref)
        changed_lines_out = os.path.join(tmp_dir, "changed-lines.json")
        Path(changed_lines_out).write_text(
            json.dumps(
                {
                    file_path: sorted(lines)
                    for file_path, lines in changed_line_map.items()
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        existing_comments, comment_errors = get_existing_pr_comments(args.repo, args.pr)
        print(f"  Existing PR comments loaded: {len(existing_comments)}")
        comments_out = os.path.join(tmp_dir, "comments.json")
        Path(comments_out).write_text(
            json.dumps(
                {"comments": existing_comments, "errors": comment_errors},
                ensure_ascii=False,
                indent=2,
            )
        )
        paragraphs_out = os.path.join(tmp_dir, "paragraphs.json")
        links_out = os.path.join(tmp_dir, "links.json")
        style_out = os.path.join(tmp_dir, "style.json")

        print("[3/4] Running checks …", flush=True)
        run_script(
            "check_paragraphs.py",
            [
                "--repo",
                repo_path,
                "--files",
                files_arg,
                "--out",
                paragraphs_out,
            ],
        )
        run_script(
            "check_links.py",
            [
                "--repo",
                repo_path,
                "--files",
                files_arg,
                "--out",
                links_out,
            ],
        )
        run_script(
            "check_style.py",
            [
                "--repo",
                repo_path,
                "--files",
                files_arg,
                "--out",
                style_out,
            ],
        )

        suppressed_findings: list[dict] = []
        out_of_scope_findings: list[dict] = []
        for findings_path in [paragraphs_out, links_out, style_out]:
            comment_suppressed, scope_suppressed = filter_findings_file(
                findings_path, existing_comments, changed_line_map
            )
            suppressed_findings.extend(comment_suppressed)
            out_of_scope_findings.extend(scope_suppressed)

        validation_errors = validate_results(paragraphs_out, links_out, style_out)
        if validation_errors:
            print("Quality check failures:")
            for e in validation_errors:
                print(f"  ✗ {e}")
            sys.exit(1)

        print("[4/4] Generating report …", flush=True)
        generate_args = [
            "--paragraphs",
            paragraphs_out,
            "--links",
            links_out,
            "--style",
            style_out,
            "--comments",
            comments_out,
            "--reviewed-files",
            reviewed_files_arg,
            "--pr",
            str(args.pr),
            "--repo",
            args.repo,
            "--out",
            out_path,
            "--comment-out",
            comment_out_path,
            "--head-repo",
            head_repo,
            "--head-ref",
            head_ref,
        ]
        if args.base_findings:
            if os.path.exists(args.base_findings):
                generate_args += ["--base-findings", args.base_findings]
            else:
                print(
                    f"  WARNING: --base-findings path not found: {args.base_findings}",
                    flush=True,
                )
        run_script("generate_report.py", generate_args)

        # Optionally persist combined findings for future follow-up review
        if args.save_findings:
            combined = []
            for path in [paragraphs_out, links_out, style_out]:
                if os.path.exists(path):
                    combined.extend(
                        json.loads(Path(path).read_text()).get("findings", [])
                    )
            Path(args.save_findings).parent.mkdir(parents=True, exist_ok=True)
            Path(args.save_findings).write_text(
                json.dumps(
                    {
                        "pr": args.pr,
                        "findings": combined,
                        "existing_comments": existing_comments,
                        "suppressed_findings": suppressed_findings,
                        "out_of_scope_findings": out_of_scope_findings,
                        "changed_line_map": {
                            file_path: sorted(lines)
                            for file_path, lines in changed_line_map.items()
                        },
                        "comment_errors": comment_errors,
                    },
                    ensure_ascii=False,
                    indent=2,
                )
            )
            print(f"  Findings saved → {args.save_findings}")

        if not os.path.exists(out_path):
            print("ERROR: report was not created.", file=sys.stderr)
            sys.exit(1)

        report_lines = Path(out_path).read_text().count("\n")
        if report_lines < 30:
            print(
                f"WARNING: report seems too short ({report_lines} lines). Check for errors."
            )

        # ::: Code Generated by Copilot [5b539fa2-769d-4c47-b6bd-d235aa805ed4]. This comment will be removed automatically after the file is saved :::
        abs_out_path = str(Path(out_path).resolve())
        abs_comment_path = str(Path(comment_out_path).resolve())
        print(f"\n✅ Review complete → {out_path}")
        print(f"📄 Absolute report path → {abs_out_path}")
        print(f"💬 Compact PR comment → {comment_out_path}")
        print(f"📝 Absolute compact comment path → {abs_comment_path}")

    except subprocess.CalledProcessError as exc:
        print(f"\nERROR running git command:\n{exc.stderr}", file=sys.stderr)
        sys.exit(1)
    finally:
        if not args.keep_tmp:
            shutil.rmtree(tmp_dir, ignore_errors=True)


if __name__ == "__main__":
    main()
